<?php declare(strict_types=1); namespace App\Repositories; use PDO; final class LiquidityEventRepository{private $pdo; public function __construct(?PDO $pdo=null){$this->pdo=$pdo??\App\Core\Database::connection();} public function create($sid,$r,$tid,$t,$d,$cash,$btc,$nft,$sh){$this->pdo->prepare('INSERT INTO liquidity_events (session_id,round_number,team_id,event_type,description,cash_delta,btc_delta,nft_delta,share_delta) VALUES (?,?,?,?,?,?,?,?,?)')->execute([$sid,$r,$tid,$t,$d,$cash,$btc,$nft,$sh]);} public function getRecentBySession($sid,$l=50){$s=$this->pdo->prepare('SELECT * FROM liquidity_events WHERE session_id=? ORDER BY id DESC LIMIT '.(int)$l);$s->execute([$sid]);return $s->fetchAll();}}
